# -*- coding: utf-8 -*-
"""Lote 2 · parte D (cirugía general: RCP, ATLS, trauma, obstrucción, hernias, colon)."""
from lote02c import Q, L, SAB, SCH

Q(a="cirugia", cat=None, tema="RCP básico con dos reanimadores", año=2018, ext=False,
  e="En el RCP básico con 2 reanimadores, ¿cuál es la relación de compresiones torácicas y ventilaciones?",
  o=["15:1.", "30:1.", "15:2.", "30:2.", "20:2."], k="D",
  c="En el adulto la relación compresión-ventilación es 30:2 tanto con uno como con dos reanimadores, sin interrupciones prolongadas: las compresiones se hacen en el centro del tórax, con una profundidad de 5-6 cm, a 100-120 por minuto y permitiendo la reexpansión completa. La relación 15:2 es la que se aplica en niños y lactantes cuando hay dos reanimadores con deber de respuesta, porque en ellos el paro suele ser de origen respiratorio y requiere más ventilaciones. Las otras opciones (15:1, 30:1, 20:2) no corresponden a ninguna recomendación vigente. Cuando el paciente ya tiene la vía aérea avanzada, las compresiones son continuas y se da una ventilación cada 6 segundos. Perla clínica: el factor que más determina la supervivencia es la calidad de las compresiones y el tiempo hasta la primera descarga si el ritmo es desfibrilable.",
  f="AHA, Guías de RCP y ACE (2025); ERC, Guías de reanimación (2021); MINSA, Guía de soporte vital básico")

Q(a="cirugia", cat=None, tema="Prioridad en el politraumatizado (ATLS)", año=2018, ext=False,
  e="Según el uso de la guía de procedimientos (ATLS), ¿cuál es la prioridad que se debe tener en cuenta en un paciente politraumatizado?",
  o=["Hemostasia.", "Hidratación.", "Vía aérea.", "Reanimación.", "Inmovilización."], k="C",
  c="El ATLS ordena la evaluación primaria con la secuencia ABCDE: A, vía aérea con protección de la columna cervical; B, ventilación y respiración; C, circulación con control de la hemorragia; D, déficit neurológico; E, exposición con control del ambiente. La prioridad es la vía aérea, porque una obstrucción mata en minutos y condiciona la oxigenación de todo lo demás. Se evalúa hablándole al paciente: si responde con voz normal, la vía aérea está permeable. Si hay sangre, vómito o cuerpos extraños se aspira; si no protege la vía aérea (Glasgow ≤ 8) se asegura con intubación orotraqueal. En la edición 11 se destaca que, en el sangrado exanguinante visible, se controla primero la hemorragia (esquema xABCDE). Las otras opciones son pasos posteriores de la secuencia.",
  f="ATLS, 11.ª ed. (2025); WSES, manejo del trauma grave (2023); MINSA, Guía de atención del trauma")

Q(a="cirugia", cat=None, tema="Politraumatizado en shock: prioridad de manejo", año=2018, ext=False,
  e="Politraumatizado que ingresa a emergencia en shock, estado inconsciente sin lesiones sangrantes. ¿Cuál debería ser la prioridad en el manejo?",
  o=["Lavado peritoneal.", "Control de la vía aérea.", "Resonancia magnética.", "Colocación de vía central.", "Radiografía simple de abdomen."], k="B",
  c="Todo politraumatizado se evalúa con la secuencia ABCDE y no se pasa al paso siguiente sin resolver el anterior. Un paciente inconsciente no protege su vía aérea y puede obstruirla con la lengua, la sangre o el vómito; además la hipoxia agrava el shock y el daño cerebral. Por eso lo primero es asegurar la vía aérea con control cervical, con intubación orotraqueal si el Glasgow es ≤ 8, y recién después se evalúa la circulación (dos vías periféricas gruesas, reposición controlada y búsqueda de la fuente de sangrado con ecografía FAST y radiografía de tórax y pelvis). El lavado peritoneal, la resonancia y la radiografía de abdomen son estudios complementarios que no se hacen antes de estabilizar. El estudio de la lesión sigue a la reanimación y no la precede.",
  f="ATLS, 11.ª ed. (2025); WSES, trauma grave (2023); " + SCH,
  nota="La clave estaba ilegible en el texto OCR; se verificó con el comentario del libro (control de la vía aérea).")

Q(a="cirugia", cat=None, tema="Isquemia mesentérica inferior: necrosis de colon izquierdo", año=2018, ext=False,
  e="Varón de 60 años, acude por dolor abdominal y signos de shock. Ingresa a sala de operaciones, evidenciándose necrosis de colon izquierdo. ¿Qué arteria se encuentra comprometida?",
  o=["Mesentérica inferior.", "Cólica derecha.", "Mesentérica superior.", "Cólica inferior.", "Cólica superior."], k="A",
  c="El colon tiene una irrigación dividida en dos territorios: la arteria mesentérica superior irriga el intestino delgado distal, el ciego, el colon ascendente y los dos tercios proximales del transverso (cólicas media, derecha e ileocólica), y la mesentérica inferior irriga el tercio distal del transverso, el colon descendente, el sigmoides y el recto superior (cólica izquierda, sigmoideas y rectal superior). La necrosis del colon izquierdo implica entonces a la mesentérica inferior. En la práctica la isquemia colónica aparece sobre todo en los puntos limítrofes (ángulo esplénico, de Griffiths, y unión rectosigmoidea, de Sudeck), tras cirugía aórtica, hipoperfusión o shock. Las opciones «cólica inferior» y «cólica superior» no existen como arterias; son distractores. Perla: la isquemia con necrosis transmural exige laparotomía y resección.",
  f="WSES, isquemia mesentérica aguda (2022); ACG, colitis isquémica (2015); " + SAB)

Q(a="cirugia", cat=None, tema="Obstrucción intestinal en paciente con peritonitis previa", año=2018, ext=False,
  e="Mujer de 60 años con dolor tipo cólico, náuseas, vómitos y estreñimiento de tres días de evolución, operada hace 5 años de peritonitis por apendicitis complicada. Examen: distensión y dolor difuso abdominal, ausencia de ruidos hidroaéreos. ¿Cuál es la causa más probable del cuadro obstructivo?",
  o=["Bridas y adherencias.", "Perforación de víscera hueca.", "Cáncer de colon.", "Trombosis de la arteria mesentérica.", "Vólvulo de sigmoides."], k="A",
  c="Una cirugía abdominal previa, sobre todo si hubo peritonitis, es el antecedente clave: las adherencias posoperatorias causan 60-75 % de las obstrucciones del intestino delgado y pueden manifestarse años después. El cuadro (dolor cólico, vómitos, estreñimiento, distensión) corresponde a una obstrucción mecánica. El cáncer de colon es la causa más frecuente de obstrucción del intestino grueso, pero suele haber cambio del hábito intestinal y pérdida de peso. El vólvulo de sigmoides aparece en ancianos con megacolon y la trombosis mesentérica produce dolor desproporcionado a la exploración física. El manejo inicial, si no hay signos de estrangulación, es conservador: ayuno, sonda nasogástrica, hidratación y vigilancia; la prueba hidrosoluble (Gastrografín) tiene valor diagnóstico y terapéutico.",
  f="WSES, obstrucción adhesiva del intestino delgado (2018, actualización 2023); " + SAB)

Q(a="cirugia", cat=None, tema="Perforación duodenal por AINE", año=2018, ext=False,
  e="Mujer de 42 años, con artritis reumatoidea en tratamiento irregular con AINE, presenta hace 8 horas dolor abdominal intenso en epigastrio que dificulta la respiración y náuseas. Examen: PA 100/60 mmHg, FR 28 por minuto, T 36,7 °C, abdomen distendido y doloroso a la palpación, Blumberg (+), McBurney (+), ruidos hidroaéreos ausentes. Rx de tórax: niveles hidroaéreos debajo de ambos hemidiafragmas. ¿Cuál es el probable diagnóstico?",
  o=["Obstrucción intestinal aguda.", "Apendicitis aguda complicada.", "Aneurisma disecante.", "Perforación duodenal.", "Diverticulitis complicada."], k="D",
  c="El uso de AINE es un factor de riesgo mayor de úlcera péptica y de su complicación más grave, la perforación. El dolor epigástrico de inicio súbito, «en puñalada», que limita la respiración, con abdomen en tabla o con irritación peritoneal generalizada y ausencia de ruidos hidroaéreos, indica peritonitis química inicial. La imagen decisiva es el neumoperitoneo: en la radiografía de tórax de pie aparece aire libre bajo ambos hemidiafragmas (la expresión «niveles hidroaéreos» del enunciado se refiere a esa interfaz aire-líquido). El Blumberg en fosa ilíaca derecha se explica porque el líquido gastroduodenal desciende por la gotiera parietocólica. El tratamiento es quirúrgico urgente: cierre simple con parche de epiplón (Graham), lavado, erradicación de H. pylori y suspensión de los AINE.",
  f="WSES, úlcera péptica perforada (2020); ACG, úlcera péptica (2024); " + SAB)

Q(a="cirugia", cat=None, tema="Neumotórax a tensión: descompresión inmediata", año=2018, ext=False,
  e="Varón de 25 años, atropellado, con disnea y dificultad respiratoria marcada, sudoración profusa y extremidades frías. PA 80/50 mmHg, FR 28 por minuto, saturación de oxígeno 85 %, desviación traqueal a nivel de la horquilla esternal, murmullo vesicular ausente en hemitórax izquierdo. Se diagnostica neumotórax a tensión. ¿Cuál es el procedimiento inmediato?",
  o=["Tracción costal izquierda.", "Descompresión torácica con angiocatéter.", "Toracotomía mínima con drenaje laminar.", "Ventilación asistida.", "Toracotomía a cielo abierto."], k="B",
  c="El neumotórax a tensión es un diagnóstico clínico y una urgencia vital: el aire entra al espacio pleural y no sale (mecanismo de válvula), colapsa el pulmón, desplaza el mediastino y reduce el retorno venoso, lo que explica la hipotensión, la hipoxemia y la desviación traqueal. No se debe esperar la radiografía. La maniobra inmediata es la descompresión con aguja o angiocatéter grueso (14 G, 8 cm en el adulto): en el 5.º espacio intercostal, línea axilar anterior (zona segura de ATLS) o, de preferencia en versiones recientes, el 2.º espacio en la línea medioclavicular según el material disponible; luego se coloca un tubo de toracostomía. La ventilación con presión positiva sin drenar empeora la tensión.",
  f="ATLS, 11.ª ed. (2025); EAST, descompresión con aguja (2022); " + SAB)

Q(a="cirugia", cat=None, tema="Politraumatizado hipotenso con anemia: ecografía FAST", año=2018, ext=False,
  e="Politraumatizado que ingresa a emergencia, con dolor abdominal difuso, palidez marcada, taquicardia e hipotensión. Hematocrito: 20 %. ¿Cuál es el procedimiento inicial de elección para el diagnóstico?",
  o=["Lavado peritoneal diagnóstico.", "Paracentesis abdominal.", "Ecografía abdominal.", "Tomografía abdominal.", "Radiografía simple de abdomen."], k="C",
  c="El paciente presenta shock hemorrágico con sospecha de hemoperitoneo. En el trauma cerrado con inestabilidad la herramienta inicial es la ecografía FAST (Focused Assessment with Sonography for Trauma) realizada en la sala de reanimación: es rápida (2-3 minutos), no invasiva, repetible y detecta líquido libre en cuatro ventanas (pericárdica, hepatorrenal o de Morrison, esplenorrenal y pélvica). Si es positiva en un paciente inestable, se va directo a laparotomía. La tomografía solo se hace en el paciente estable, porque requiere traslado. El lavado peritoneal diagnóstico es más invasivo y casi no se usa cuando se dispone de ecografía. La radiografía de abdomen no aporta en este contexto. Perla clínica: la FAST no descarta lesión retroperitoneal ni de víscera hueca.",
  f="ATLS, 11.ª ed. (2025); WSES, trauma abdominal cerrado (2017); " + SCH)

Q(a="cirugia", cat=None, tema="Trauma abdominal con hipotensión y líquido libre: laparotomía", año=2018, ext=False,
  e="Varón de 30 años, sufre agresión con objeto contundente en abdomen, refiere dolor difuso en mesogastrio y flanco derecho. Examen: palidez, extremidades frías, sudoración, hipotensión y ruidos hidroaéreos ausentes. Hematocrito: 15 %. Ecografía: líquido libre de aproximadamente 500 cc en flanco derecho. ¿Qué medida se debe seguir?",
  o=["Observación controlada.", "Tomografía abdominal.", "Lavado peritoneal.", "Laparotomía exploratoria.", "Transfusión de coloides."], k="D",
  c="La combinación de trauma abdominal cerrado, hipotensión, anemia severa y líquido libre en la ecografía indica hemoperitoneo con inestabilidad hemodinámica, y la conducta es la laparotomía exploratoria urgente: el control del sangrado es quirúrgico y no se debe retrasar con estudios por imagen. Mientras se prepara al paciente se aplica reanimación con control de daños: transfusión balanceada de hemoderivados (concentrado de hematíes, plasma y plaquetas en relación cercana a 1:1:1), limitación de cristaloides, hipotensión permisiva (PAS 80-90 mmHg si no hay trauma craneal), ácido tranexámico en la primera hora y evitar hipotermia. La tomografía se reserva para el paciente estable o con respuesta transitoria. Los coloides sintéticos no están recomendados en el trauma.",
  f="WSES, trauma abdominal cerrado (2017); Guía europea de sangrado y coagulopatía en trauma (2023); ATLS, 11.ª ed. (2025)")

Q(a="cirugia", cat=None, tema="Absceso hepático posoperatorio: examen de elección", año=2018, ext=False,
  e="Mujer de 65 años, posoperada de 15 días por diverticulitis complicada Hinchey III (sigmoidectomía y colostomía de Hartmann). Dolor en cuadrante superior derecho. PA 100/50 mmHg, T 39,5 °C, FC 110 por minuto, ictericia de escleras, dolor e hipertrofia en hipocondrio derecho, hepatomegalia. Leucocitos 15 000/µL. Rx de tórax: elevación del hemidiafragma derecho; ecografía normal. ¿Cuál es el examen de elección para el diagnóstico?",
  o=["Tomografía helicoidal multicorte.", "Colangiografía endoscópica.", "Resonancia magnética nuclear.", "Gammagrafía hepática.", "Radiografía simple de abdomen."], k="A",
  c="Fiebre alta, dolor en hipocondrio derecho, hepatomegalia y elevación del hemidiafragma derecho en una paciente con sepsis abdominal reciente sugieren un absceso hepático o subfrénico (piógeno, por diseminación portal desde el foco diverticular). Una ecografía normal no lo descarta, porque su sensibilidad depende del operador, de los gases intestinales y del tamaño de la lesión. La tomografía contrastada multicorte es el estudio de elección: detecta abscesos de 0,5 cm, define su número y localización, evalúa colecciones abdominales residuales y orienta el drenaje percutáneo guiado por imagen. La CPRE se reserva para patología biliar y la resonancia es alternativa si hay contraindicación. Tratamiento: antibióticos de amplio espectro, drenaje percutáneo y control del foco primario.",
  f="IDSA/SIS, infección intraabdominal complicada (2017, 2024); WSES (2017); " + SAB)

Q(a="cirugia", cat=None, tema="Estridor en anafilaxia: vía aérea quirúrgica", año=2018, ext=False,
  e="Varón de 27 años, luego de aplicarse una ampolla de penicilina, presenta dificultad respiratoria severa. FR 32 por minuto, saturación de oxígeno 70 %, pulso 110 por minuto, edema de cara y cuello, murmullo vesicular que pasa con dificultad, estridor laríngeo. Se diagnostica shock anafiláctico. ¿Cuál es el procedimiento de elección para permeabilizar la vía aérea?",
  o=["Oxigenación con máscara.", "Intubación orotraqueal.", "Traqueostomía.", "Cricotiroidotomía.", "Intubación nasotraqueal."], k="D",
  c="En la anafilaxia el tratamiento inicial es adrenalina intramuscular 0,3-0,5 mg (0,01 mg/kg) en la cara anterolateral del muslo, oxígeno y reposición de volumen. El edema de la glotis con estridor y saturación de 70 % indica una vía aérea en riesgo inminente. Si la intubación orotraqueal por un experto falla o es imposible por el edema (situación «no intubo, no oxigeno»), el procedimiento de rescate es la cricotiroidotomía, rápida (menos de un minuto), con referencias palpables y sin necesidad de manipular el cuello. La traqueostomía de urgencia consume más tiempo y tiene más complicaciones. La intubación nasotraqueal a ciegas no es adecuada en un laringe edematizada. Se completa con antihistamínicos, corticoides y observación de 6-24 horas por riesgo de reacción bifásica.",
  f="World Allergy Organization, anafilaxia (2020, 2024); EAACI (2021); Difficult Airway Society (2015, 2025); ATLS, 11.ª ed. (2025)",
  nota="El libro marca cricotiroidotomía; en la práctica se intenta primero la intubación por el operador más experto y la vía aérea quirúrgica es la opción de rescate.")

Q(a="cirugia", cat=None, tema="Hernia femoral estrangulada", año=2018, ext=False,
  e="Multípara de 39 años, hace 8 horas presenta tumoración dolorosa en región inguinal derecha, náuseas, vómitos alimentarios y distensión abdominal. PA 100/60 mmHg, FC 110 por minuto, T 36,7 °C, abdomen distendido y doloroso, ruidos hidroaéreos ausentes, masa de 2 × 3 cm violácea y muy dolorosa por debajo de la espina ilíaca anterosuperior. Leucocitosis 14 000/µL con 10 abastonados. ¿A qué tipo de hernia corresponde?",
  o=["Semilunar.", "Inguinal estrangulada.", "Inguinal encarcelada.", "Obturatriz.", "Femoral estrangulada."], k="E",
  c="La hernia femoral protruye por debajo del ligamento inguinal, a través del anillo femoral, por dentro de la vena femoral. Es más frecuente en mujeres multíparas y tiene un cuello estrecho y rígido (ligamento lacunar), por lo que se complica con frecuencia: casi 40 % se presenta como estrangulada. La masa pequeña, dura y dolorosa, por debajo del ligamento inguinal, con cambio de coloración violáceo, leucocitosis con abastonados y signos de obstrucción (vómitos, distensión, ausencia de ruidos) indica compromiso vascular: estrangulación. La diferencia con la hernia inguinal es su posición por debajo de la línea que une la espina ilíaca anterosuperior con el tubérculo púbico. Tratamiento: cirugía urgente, resección intestinal si hay necrosis y reparación sin tensión (malla o abordaje inguinal o femoral).",
  f="EHS/HerniaSurge, hernia de la ingle (2018); WSES, hernias de la pared abdominal complicadas (2023); " + SAB)

Q(a="cirugia", cat=None, tema="Causa más frecuente de obstrucción intestinal en adultos", año=2018, ext=False,
  e="¿Cuál es la causa más frecuente de obstrucción intestinal en adultos?",
  o=["Intususcepción.", "Bridas y adherencias.", "Vólvulo de sigmoides.", "Trombosis mesentérica.", "Cáncer de colon."], k="B",
  c="En el adulto, las adherencias posoperatorias (bridas) son la causa número uno de obstrucción del intestino delgado a nivel mundial (60-75 %), seguidas de las hernias de la pared abdominal complicadas y las neoplasias. En el intestino grueso la primera causa es el cáncer colorrectal, seguido del vólvulo de sigmoides y la enfermedad diverticular. La intususcepción es una causa frecuente en lactantes y rara en adultos, donde casi siempre es secundaria a una lesión guía. La trombosis mesentérica no obstruye mecánicamente; produce isquemia. El 90 % de los casos de obstrucción por adherencias son parciales y el 70-80 % se resuelve con manejo no operatorio. Perla: si hay fiebre, taquicardia, leucocitosis, peritonismo o acidosis, hay que sospechar estrangulación y operar.",
  f="WSES, obstrucción adhesiva del intestino delgado (2018); " + SAB + "; " + SCH)

Q(a="cirugia", cat=None, tema="Colangitis aguda: examen de elección", año=2018, ext=False,
  e="¿Cuál es el examen de elección para el diagnóstico de colangitis aguda?",
  o=["Colecistografía endovenosa.", "Ecografía abdominal.", "Colangiografía endoscópica.", "Punción transparietohepática.", "Tomografía abdominal."], k="C",
  c="La colangitis aguda es una infección de la vía biliar con obstrucción (litiasis, estenosis, neoplasias): triada de Charcot (dolor en hipocondrio derecho, fiebre con escalofríos e ictericia) y pentada de Reynolds si hay hipotensión y confusión. Los criterios de Tokio (TG18) combinan inflamación sistémica, colestasis y evidencia por imagen. El primer estudio es la ecografía (dilatación de la vía biliar, litos), pero el procedimiento que confirma y trata a la vez es la colangiopancreatografía retrógrada endoscópica (CPRE), que permite drenar la vía biliar y extraer cálculos. En el grado leve basta tratamiento antibiótico, y se drena en 24-48 horas; en el grado II se drena en 24 horas y en el grado III el drenaje es urgente. La colangiografía transparietal queda como alternativa si la CPRE falla.",
  f="Guías de Tokio 2018 (TG18); ESGE, CPRE y colangitis (2021); ASGE, coledocolitiasis (2019)")

Q(a="cirugia", cat=None, tema="Obstrucción parcial del intestino delgado: tratamiento inicial", año=2018, ext=False,
  e="Varón de 40 años, con diagnóstico de obstrucción parcial del intestino delgado. ¿Cuál es el tratamiento inicial?",
  o=["Laparotomía exploradora.", "Administración de gastrocinéticos.", "Sonda nasogástrica y rehidratación.", "Resección intestinal con anastomosis.", "Reposición hidroelectrolítica."], k="C",
  c="La obstrucción parcial del intestino delgado sin datos de estrangulación se maneja inicialmente de forma no operatoria: ayuno, descompresión con sonda nasogástrica, reposición de líquidos y electrolitos (cristaloides, corrección de potasio) y vigilancia clínica seriada cada 6-12 horas. Más de 70 % se resuelve en 48-72 horas. Se agrega prueba con contraste hidrosoluble (Gastrografín), que predice resolución si llega al colon en 24 horas y puede acelerarla. Se opera si hay peritonitis, isquemia, fiebre, acidosis, leucocitosis creciente o falta de resolución después de 3 días. Los procinéticos están contraindicados en la obstrucción mecánica. La reposición hidroelectrolítica sola no descomprime, por lo que la mejor respuesta combina descompresión y rehidratación.",
  f="WSES, obstrucción adhesiva del intestino delgado (2018); " + SAB)

Q(a="cirugia", cat=None, tema="Politraumatizado inestable sin dificultad respiratoria", año=2018, ext=False,
  e="En un paciente politraumatizado que ingresa con inestabilidad hemodinámica y sin dificultad respiratoria, ¿cuál es el manejo terapéutico prioritario?",
  o=["Antibioticoterapia.", "Catéter venoso central.", "Intubación endotraqueal.", "Collarín cervical.", "Control del sangrado."], k="E",
  c="Durante la evaluación primaria (ABCDE) se resuelven los problemas en orden. Un paciente que habla y no tiene dificultad respiratoria tiene la vía aérea y la ventilación en condiciones aceptables (A y B), por lo que el problema prioritario es la circulación (C): la causa más frecuente de inestabilidad en el trauma es la hemorragia, y por eso el control del sangrado tiene la máxima prioridad. Se aplican compresión directa o torniquete en hemorragias externas, faja pélvica en fracturas de pelvis, dos vías periféricas de grueso calibre, transfusión balanceada, ácido tranexámico y cirugía de control de daños. La inmovilización cervical se coloca simultáneamente, pero no es la intervención terapéutica que salva la vida. El acceso venoso central no se necesita en la fase inicial y la antibioticoterapia se da después.",
  f="ATLS, 11.ª ed. (2025); Guía europea de sangrado y coagulopatía en trauma (2023); WSES (2023)")

Q(a="cirugia", cat=None, tema="Manejo inicial del gran quemado", año=2018, ext=False,
  e="¿Quiénes son los responsables del manejo inicial del gran quemado?",
  o=["Dermatólogos.", "Equipo multidisciplinario.", "Cirujanos generales.", "Médicos internistas.", "Cirujanos plásticos."], k="B",
  c="El gran quemado (superficie corporal quemada > 20-25 % o lesiones graves de cara, manos, genitales, inhalatorias o eléctricas) es un paciente crítico con respuesta inflamatoria sistémica, hipovolemia, riesgo de lesión inhalatoria y sepsis. Su atención inicial debe ser de un equipo multidisciplinario en una unidad de quemados: emergencia (ABCDE), intensivista, cirujano plástico, anestesiólogo, enfermería especializada, nutrición, rehabilitación, psicología y soporte social. La reanimación hídrica se inicia con cristaloides (Ringer lactato), con la fórmula de Parkland (2-4 mL/kg por % de superficie quemada en 24 horas, la mitad en las primeras 8 horas) y se ajusta a una diuresis de 0,5 mL/kg/h. Se cubren las heridas, se previene la hipotermia y se refiere de manera temprana a un centro de quemados.",
  f="ABA, Guías de remisión a centros de quemados (2022); ISBI, Guías de práctica (2016, 2022); ATLS, 11.ª ed. (2025); MINSA, Guía de quemaduras")

Q(a="cirugia", cat=None, tema="Clasificación de Hinchey: absceso pélvico", año=2018, ext=False,
  e="La colección pélvica de secreción purulenta por un cuadro clínico de diverticulitis complicada, ¿a qué estadio corresponde según la clasificación de Hinchey?",
  o=["II.", "III.", "IV.", "IIIC.", "IIIA."], k="A",
  c="La clasificación de Hinchey describe la diverticulitis complicada: I, absceso pericólico o flemón (< 5 cm); II, absceso pélvico, intraabdominal o retroperitoneal a distancia del foco (por lo general > 5 cm); III, peritonitis purulenta generalizada; IV, peritonitis fecal. Por eso una colección pélvica de pus corresponde al estadio II. En la clasificación modificada se subdivide el I en Ia (flemón) e Ib (absceso pericólico) y el II en IIa (absceso accesible a drenaje percutáneo) y IIb (complejo, con fístula). Los abscesos mayores de 4-5 cm se drenan por vía percutánea guiada por tomografía más antibióticos; si no es posible o el paciente se deteriora, se hace cirugía (Hartmann o resección con anastomosis y estoma de protección). En Hinchey III se prefieren el lavado laparoscópico o la sigmoidectomía.",
  f="WSES, diverticulitis aguda (2020); ASCRS, enfermedad diverticular (2020); ESCP (2020)")

Q(a="cirugia", cat=None, tema="Ascitis exudativa linfocitaria: biopsia peritoneal", año=2019, ext=False,
  e="Varón de 50 años con dolor abdominal difuso, fiebre y ascitis de 2 meses de evolución, sin antecedentes de importancia. Paciente adelgazado, pálido, T 38 °C, PA 110/70 mmHg. Abdomen distendido con dolor difuso y signo de la oleada positivo. Líquido ascítico exudativo con aumento de linfocitos. ¿Qué examen o procedimiento ayuda al diagnóstico definitivo?",
  o=["Velocidad de sedimentación globular elevada.", "ADA de líquido ascítico.", "Resonancia magnética.", "Tomografía abdominopélvica.", "Biopsia peritoneal."], k="E",
  c="La ascitis exudativa linfocitaria crónica (gradiente seroalbúmina-ascitis < 1,1 g/dL, proteínas > 2,5 g/dL) con fiebre, pérdida de peso y síntomas de 2 meses sugiere en el Perú, en primer lugar, peritonitis tuberculosa; otras causas son carcinomatosis peritoneal, mesotelioma y linfoma. La adenosina deaminasa (ADA > 39 U/L) tiene buena sensibilidad y especificidad y orienta, pero no es diagnóstica; la tomografía muestra engrosamiento peritoneal y ganglios necróticos. El diagnóstico definitivo se logra con la histología (granulomas caseificantes) o cultivo, y la biopsia peritoneal, preferentemente por laparoscopía (sensibilidad > 95 %), es el estándar. El cultivo del líquido tiene bajo rendimiento y la citología detecta células malignas en carcinomatosis. Se debe iniciar tratamiento antituberculoso si hay alta sospecha.",
  f="AASLD, ascitis (2021); ATS/CDC/IDSA/ERS, TB (2016) y OMS, TB (2022); NTS MINSA, atención de la TB (2013, actualizaciones)",
  nota="Fiebre y pérdida de peso con ascitis linfocitaria: la ADA orienta pero la biopsia peritoneal es la que da el diagnóstico de certeza.")

Q(a="cirugia", cat=None, tema="Clasificación de Nyhus: hernia indirecta deslizada", año=2019, ext=False,
  e="Varón de 45 años con hernia inguinal derecha no complicada; durante la intervención quirúrgica el cirujano evidencia que el saco herniario protruye por fuera de los vasos epigástricos y como contenido el ciego. De acuerdo a la clasificación de Nyhus, ¿a qué tipo corresponde?",
  o=["II.", "IV.", "III.", "IIIB.", "IIIA."], k="D",
  c="La clasificación de Nyhus ordena las hernias inguinales así: tipo I, indirecta con anillo interno normal (en niños); II, indirecta con anillo interno dilatado, sin afectar la pared posterior; III, defecto de la pared posterior: IIIA directa, IIIB indirecta con anillo muy dilatado que invade la pared posterior (incluye las deslizadas y las voluminosas «pantalón») y IIIC femoral; IV, hernias recurrentes (A directa, B indirecta, C femoral, D combinada). El saco lateral a los vasos epigástricos es indirecto; que contenga el ciego implica deslizamiento y un daño de la pared posterior, por lo que es IIIB. La reparación sin tensión con malla es el estándar, por vía abierta (Lichtenstein) o laparoscópica (TEP o TAPP).",
  f="EHS/HerniaSurge, hernia de la ingle (2018); Clasificación de Nyhus (1993); " + SAB,
  nota="La clave de la opción D estaba parcialmente ilegible en el OCR; se verificó que corresponde a IIIB.")

Q(a="cirugia", cat=None, tema="Trauma abdominal cerrado estable con líquido libre mínimo", año=2019, ext=False,
  e="Mujer de 36 años llega a emergencia por haber sufrido accidente de tránsito. PA 130/70 mmHg, FC 98 por minuto, saturación de oxígeno 97 %, T 36,5 °C, Glasgow 15, abdomen distendido y doloroso a predominio superior, Blumberg (−), ruidos hidroaéreos disminuidos. Ecografía abdominal: líquido libre de aproximadamente 50 cc en el Morrison. ¿Cuál es la conducta a seguir?",
  o=["Lavado peritoneal diagnóstico.", "Tomografía abdominal.", "Paracentesis abdominal.", "Laparoscopía diagnóstica.", "Laparotomía exploratoria."], k="B",
  c="En el trauma abdominal cerrado la conducta la define la estabilidad hemodinámica. La paciente tiene presión y frecuencia cardiaca normales, Glasgow 15 y sin peritonismo: es una paciente estable con ecografía FAST positiva para una pequeña cantidad de líquido, y debe ser estudiada con tomografía abdominopélvica con contraste, que identifica la víscera lesionada, el grado de la lesión y el sangrado activo. Con ello se decide el manejo no operatorio (lesiones hepáticas y esplénicas de grado bajo-medio, con vigilancia en cama y hemograma seriado), la angioembolización o la cirugía. Solo la inestabilidad, la peritonitis o la evisceración llevan directo a laparotomía. El lavado peritoneal y la paracentesis han sido reemplazados por la ecografía y la tomografía.",
  f="WSES, trauma abdominal cerrado (2017); EAST, manejo no operatorio del trauma abdominal; ATLS, 11.ª ed. (2025)",
  nota="El libro marca laparotomía exploratoria (E); las guías ATLS y WSES recomiendan tomografía en el paciente estable, por lo que se corrigió la clave a B.")

Q(a="cirugia", cat=None, tema="Cáncer de colon del ángulo esplénico", año=2019, ext=False,
  e="Paciente de 50 años con un mes de pérdida de peso, astenia, anorexia, estreñimiento y dolor abdominal inferior. Dolor discreto en flanco izquierdo. Colonoscopía: lesión ulcerada en la flexura esplénica del colon. Biopsia: adenocarcinoma. ¿Cuál es el tratamiento quirúrgico?",
  o=["Colectomía subtotal.", "Colectomía izquierda extendida.", "Colectomía sigmoidea.", "Colectomía izquierda.", "Colectomía transversa."], k="B",
  c="El tratamiento del cáncer de colon es la resección oncológica del segmento con ligadura vascular en su origen y linfadenectomía (al menos 12 ganglios). La flexura esplénica tiene una irrigación doble, porque la zona limítrofe depende de la cólica media (mesentérica superior) y de la cólica izquierda (mesentérica inferior), de modo que las resecciones segmentarias (transversa o izquierda) comprometen el margen o la perfusión. Por eso la intervención recomendada es la colectomía izquierda extendida (hemicolectomía izquierda ampliada) con resección del transverso distal, el ángulo, el colon descendente y a veces el sigmoides, ligando cólica media izquierda y mesentérica inferior. La colectomía subtotal se reserva para síndromes hereditarios o tumores sincrónicos. Se agrega quimioterapia adyuvante si hay ganglios positivos (estadio III).",
  f="NCCN, cáncer de colon (2025); ESMO, cáncer de colon (2023); ASCRS (2022); " + SAB)

Q(a="cirugia", cat=None, tema="Obstrucción adhesiva sin estrangulación: observación", año=2019, ext=False,
  e="Paciente de 60 años con dolor abdominal tipo cólico, náuseas, vómito y estreñimiento desde hace cuatro días; apendicectomía hace 40 años. Distensión abdominal, discreto dolor a la palpación, ruidos hidroaéreos disminuidos. Rx de abdomen: niveles hidroaéreos. Laboratorio sin alteraciones. Impresión diagnóstica: obstrucción intestinal. ¿Cuál es la conducta a seguir?",
  o=["Laparotomía exploradora.", "Nutrición parenteral total.", "Observación, sonda nasogástrica e hidratación parenteral.", "Tomografía computarizada abdominal.", "Laparotomía más liberación de adherencias."], k="C",
  c="El paciente tiene una obstrucción adhesiva probable (cirugía previa), sin signos de alarma: dolor leve, sin peritonismo, laboratorio normal. La conducta es el manejo conservador: ayuno, sonda nasogástrica para descomprimir, hidratación parenteral con corrección de electrolitos y observación con examen abdominal seriado. Cerca del 70-80 % se resuelve en 48-72 horas. Se agrega una prueba de contraste hidrosoluble como pronóstico y terapia. La cirugía inmediata queda para los casos con estrangulación (fiebre, taquicardia, leucocitosis, acidosis, dolor continuo, peritonismo), el hallazgo en la TC de signos de isquemia, o la falta de mejoría después de 72 horas. La nutrición parenteral se considera si el ayuno se prolonga más de 5-7 días.",
  f="WSES, obstrucción adhesiva del intestino delgado (2018); " + SAB)

Q(a="cirugia", cat=None, tema="Ictericia súbita en paciente con colelitiasis: CPRE", año=2019, ext=False,
  e="Mujer de 30 años con diagnóstico de colecistitis litiásica hace tres años presenta dolor en hipocondrio derecho en forma súbita desde hace 24 horas, con ictericia. ¿Cuál es la conducta a seguir?",
  o=["Colecistectomía abierta con exploración de vía biliar.", "Tomografía computarizada abdominal.", "Ecografía abdominal.", "CPRE con extracción endoscópica del cálculo en el colédoco.", "Colecistectomía laparoscópica y exploración de vía biliar."], k="D",
  c="Cólico biliar con ictericia en una paciente con colelitiasis conocida sugiere coledocolitiasis. Las guías ASGE 2019 estratifican el riesgo: alto riesgo (cálculo visible en ecografía, colangitis, o bilirrubina total > 4 mg/dL con colédoco dilatado) se va directo a CPRE terapéutica; riesgo intermedio (alteración de pruebas hepáticas, edad > 55, colédoco dilatado) requiere ecoendoscopía o colangiorresonancia previa. La mujer joven con ictericia y dolor agudo tiene alta probabilidad de coledocolitiasis, y la CPRE con papilotomía y extracción permite resolver la obstrucción y prevenir colangitis y pancreatitis biliar. Después se hace colecistectomía laparoscópica en la misma hospitalización para evitar recurrencias. La exploración quirúrgica de la vía biliar se reserva para la falla endoscópica.",
  f="ASGE, coledocolitiasis (2019); ESGE, cálculos de la vía biliar (2019); Guías de Tokio 2018 (TG18)")

Q(a="cirugia", cat=None, tema="Apendicitis aguda en el adulto mayor", año=2019, ext=False,
  e="Varón de 86 años con 96 horas de dolor abdominal en cuadrante inferior derecho, asociado a náuseas sin vómito e hiporexia. PA 120/60 mmHg, T 37,5 °C, FC 100 por minuto, saturación de oxígeno 96 %. Abdomen: dolor a la palpación en fosa ilíaca derecha; McBurney (−), Blumberg (−). Hemograma: leucocitos 10 000/µL con 8 % de abastonados. ¿Cuál es la conducta a seguir?",
  o=["Apendicectomía.", "Antibioticoterapia y observación.", "Tomografía abdominal.", "Ecografía abdominal.", "Resonancia magnética."], k="A",
  c="El anciano es «oligosintomático»: la respuesta inflamatoria y la clínica están atenuadas, por lo que la apendicitis se diagnostica tarde (más perforaciones, 30-50 %) y tiene mayor mortalidad. Un dolor persistente en la fosa ilíaca derecha de 4 días con desviación izquierda es suficiente para sospechar apendicitis aguda. Aquí se suman dolor en la fosa ilíaca derecha (2), náuseas (1), anorexia (1), temperatura (1) y desviación izquierda (1): 6 o más puntos, probabilidad intermedia-alta que, en un anciano, justifica la apendicectomía. En el adulto mayor la tomografía es un estudio útil si hay dudas diagnósticas porque descarta neoplasia de ciego, diverticulitis o isquemia, pero no debe retrasar la cirugía cuando la probabilidad es alta. El tratamiento antibiótico exclusivo tiene más recurrencia y fallas en esta población.",
  f="WSES, apendicitis aguda (2020); EAES (2016); " + SAB,
  nota="El libro suma 7 puntos de Alvarado e indica cirugía. Si la presentación fuera equívoca, la TC es la opción siguiente.")
